INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein M.2-Port immer schneller als SATA ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Protokoll"}, {"text": "Ja", "correct": false, "because": "Nicht immer schneller"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich einen M.2-Port für eine SSD auswähle?', 3, '[{"text": "Kompatibilität", "correct": true, "because": "Sichert Funktion"}, {"text": "Farbe", "correct": false, "because": "Irrelevant"}, {"text": "Gewicht", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen einen M.2-Port nützlich?', 5, '[{"text": "Hohe Bandbreite", "correct": true, "because": "Fördert Geschwindigkeit"}, {"text": "Kompakte Größe", "correct": true, "because": "Platzsparend"}, {"text": "Hohe Latenz", "correct": false, "because": "Nachteil"}, {"text": "Schwere Bauweise", "correct": false, "because": "Nicht erwünscht"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) M.2-Ports unterstützen NVMe. b) Sie sind immer für Grafikkarten geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht für Grafikkarten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich einen M.2-Port für eine SSD auswähle?', 4, '[{"text": "Protokollunterstützung", "correct": false, "because": "Bestimmt Geschwindigkeit"}, {"text": "Größenkompatibilität", "correct": false, "because": "Sichert Passform"}, {"text": "Portfarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein M.2-Port immer NVMe unterstützt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch SATA möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich einen M.2-Port für eine SSD nutze?', 3, '[{"text": "Hohe Geschwindigkeit", "correct": true, "because": "Verbessert Leistung"}, {"text": "Geringere Kosten", "correct": false, "because": "Nicht primär"}, {"text": "Schwere Bauweise", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind bei einem M.2-Port entscheidend?', 5, '[{"text": "Schnittstellentyp", "correct": true, "because": "Bestimmt Protokoll"}, {"text": "Bandbreitenkapazität", "correct": true, "because": "Fördert Datenrate"}, {"text": "Hohe Latenz", "correct": false, "because": "Nachteil"}, {"text": "Bunte Optik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) M.2-Ports sind schneller als SATA-Ports. b) Sie sind immer für WLAN-Karten geeignet. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht alle für WLAN"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, wenn ich einen M.2-Port für eine SSD auswähle?', 4, '[{"text": "Key-Typ", "correct": false, "because": "Sichert Kompatibilität"}, {"text": "Protokoll", "correct": false, "because": "Bestimmt Leistung"}, {"text": "Portdekoration", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Unterstützt ein M.2-Port immer SATA und NVMe gleichzeitig?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig vom Mainboard"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein M.2-Port für SSDs?', 4, '[{"text": "Hohe Datenrate", "correct": true, "because": "Verbessert Zugriff"}, {"text": "Kompakte Größe", "correct": true, "because": "Platzsparend"}, {"text": "Hohe Latenz", "correct": false, "because": "Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass M.2-Ports nur für SSDs genutzt werden. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für WLAN oder andere Geräte"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um einen M.2-Port für eine NVMe-SSD auszuwählen?', 3, '[{"text": "NVMe-Unterstützung", "correct": true, "because": "Sichert Kompatibilität"}, {"text": "Geringe Größe", "correct": false, "because": "Sekundär"}, {"text": "Bunte Markierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) M.2-Ports erhöhen die SSD-Geschwindigkeit. b) Sie sind immer teurer als SATA.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren berücksichtige ich bei einem M.2-Port?', 5, '[{"text": "Größenstandard", "correct": true, "because": "Sichert Passform"}, {"text": "Protokolltyp", "correct": true, "because": "Bestimmt Geschwindigkeit"}, {"text": "Portgewicht", "correct": false, "because": "Irrelevant"}, {"text": "Büroausstattung", "correct": false, "because": "Kein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich einen M.2-Port für eine SSD auswähle?', 3, '[{"text": "Key-Kompatibilität", "correct": false, "because": "Sichert Funktion"}, {"text": "Bandbreite", "correct": false, "because": "Entscheidend für Leistung"}, {"text": "Portfarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind M.2-Ports immer auf Mainboards vorhanden?', 3, '[{"text": "Nein", "correct": true, "because": "Abhängig vom Modell"}, {"text": "Ja", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein M.2-Port nur für Speichergeräte geeignet ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für WLAN etc."}, {"text": "Ja", "correct": false, "because": "Vielseitig nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist entscheidend für einen M.2-Port?', 4, '[{"text": "Hohe Bandbreitenunterstützung", "correct": true, "because": "Fördert Leistung"}, {"text": "Geringes Gewicht", "correct": false, "because": "Sekundär"}, {"text": "Bunte Optik", "correct": false, "because": "Irrelevant"}]');
